/// A lexicon method: `query` (GET) or `procedure` (POST).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MethodKind {
    Query,
    Procedure,
}

impl MethodKind {
    /// The HTTP method this kind is served over.
    pub fn http_method(&self) -> &'static str {
        match self {
            Self::Query => "GET",
            Self::Procedure => "POST",
        }
    }
}

