/// Looks a method up by NSID.
pub fn find(nsid: &str) -> Option<&'static Method> {
    METHODS.iter().find(|method| method.nsid == nsid)
}

/// Every query's NSID.
pub fn queries() -> impl Iterator<Item = &'static str> {
    METHODS
        .iter()
        .filter(|method| method.kind == MethodKind::Query)
        .map(|method| method.nsid)
}

/// Every procedure's NSID.
pub fn procedures() -> impl Iterator<Item = &'static str> {
    METHODS
        .iter()
        .filter(|method| method.kind == MethodKind::Procedure)
        .map(|method| method.nsid)
}
